-- DISCARD the 30 old 'math harder' draft versions created by 44 (marked mathHarder1020: Math Module 2 higher hard 8 -> 11, Math Module 1 easy 8 -> 5 medium). Drafts only, never published, no attempts can reference them; published sets untouched. Run once before 49 (49 skips a set that still has a draft).
-- generated by scripts/prod-open/sat-expand-sql.ts (SAT_MATH_HARD5=1). Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.

do $dd$ declare v_n int; begin
  delete from mock_exam_sets s where s.status = 'draft' and s.archived_at is null and s.readiness_report->>'mathHarder1020' = 'true' and not exists (select 1 from mock_exam_attempts a where a.exam_set_id = s.id)
    and exists (select 1 from mock_exam_sets p where p.set_group_id = s.set_group_id and p.status = 'published' and p.version_no < s.version_no);
  get diagnostics v_n = row_count; raise notice 'old math-harder drafts removed: %', v_n;
end $dd$;
